import csv
from datetime import datetime, timedelta
tsid='20f10a84-4ec1-54ad-896a-1b534d833709'
d = {}
for v in csv.DictReader(open(VALUES_CSV)):
    if v['timeseries_id']==tsid:
        key=v['timestamp']
        d[key]=float(v['value'])

# group by date in Oct 2018
from collections import defaultdict
days=defaultdict(list)
for k,val in d.items():
    dt=datetime.strptime(k,'%Y-%m-%dT%H:%M:%S')
    if dt.year==2018 and dt.month==10:
        days[dt.date()].append(('H',val))

# Only dates with all 24 hourly values
valid={day:vals for day,vals in days.items() if len(vals)==24}
tot={}
for day,vals in days.items():
    tot[day]=sum(x[1] for x in vals)
vdays=sorted([day for day in days if len(days[day])==24])
print('valid days',len(vdays))
vals=[tot[day] for day in vdays]
mean=sum(vals)/len(vals)
cnt=sum(1 for day in vdays if tot[day]>1.10*mean)
print('mean',mean,'count',cnt)
